"use client";

import * as React from "react";
import { motion, useReducedMotion, useSpring } from "motion/react";
import { ChevronLeft, ChevronRight, type LucideIcon } from "lucide-react";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuItem,
  sidebarMenuButtonVariants,
  useSidebar,
} from "@/components/aria/sidebar";
import { cn } from "@/lib/utils";

export type NavItem = {
  to: string;
  label: string;
  icon: LucideIcon;
  badge?: string;
  dataTour?: string;
  active?: boolean;
  onClick?: () => void;
};

type BendingRailProps = {
  side?: "left" | "right";
};

/**
 * Stripe-style bending edge rail. SVG path bows outward toward the cursor.
 * Click toggles sidebar collapse. Honors prefers-reduced-motion.
 */
function BendingRail({ side = "left" }: BendingRailProps) {
  const { toggleSidebar, state } = useSidebar();
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const [yPct, setYPct] = React.useState(0.5);
  const [hover, setHover] = React.useState(false);

  const bow = useSpring(0, { stiffness: 380, damping: 28 });

  // Bow in the direction the click will move the edge: into the sidebar when
  // expanded (a click collapses, pulling the edge inward), out toward the
  // content when collapsed (a click expands, pushing the edge outward).
  // Matches the chevron chip below. The spring is driven by the interactions
  // themselves — enter, leave, click — not synced through an effect.
  const outward = side === "left" ? 10 : -10;
  const bowFor = (s: typeof state) => (reduced ? 0 : s === "collapsed" ? outward : -outward);

  const onEnter = () => {
    setHover(true);
    bow.set(bowFor(state));
  };
  const onLeave = () => {
    setHover(false);
    bow.set(0);
  };
  const onToggle = () => {
    toggleSidebar();
    // The pointer is still on the rail: re-aim for the state the click just
    // produced.
    bow.set(bowFor(state === "collapsed" ? "expanded" : "collapsed"));
  };

  const onMove = (e: React.PointerEvent<HTMLButtonElement>) => {
    if (!ref.current) return;
    const rect = ref.current.getBoundingClientRect();
    const ratio = (e.clientY - rect.top) / rect.height;
    setYPct(Math.max(0, Math.min(1, ratio)));
  };

  const [bowVal, setBowVal] = React.useState(0);
  React.useEffect(() => bow.on("change", setBowVal), [bow]);

  const ctrlY = yPct * 100;
  const d = `M 6 0 Q ${6 + bowVal} ${ctrlY} 6 100`;

  return (
    <button
      ref={ref}
      type="button"
      data-sidebar="rail"
      aria-label="Toggle sidebar"
      onClick={onToggle}
      onPointerEnter={onEnter}
      onPointerLeave={onLeave}
      onPointerMove={onMove}
      className={cn(
        "absolute inset-y-0 z-[var(--z-rail)] hidden w-3 sm:flex",
        side === "left"
          ? "right-0 translate-x-1/2 cursor-w-resize"
          : "left-0 -translate-x-1/2 cursor-e-resize",
        state === "collapsed" && (side === "left" ? "cursor-e-resize" : "cursor-w-resize"),
      )}
    >
      {/* No backdrop-filter here: blurring the 12px strip straddling the
          boundary rendered as its own tinted band — a visible color seam
          between sidebar and content. The line alone marks the edge. */}
      <svg viewBox="0 0 12 100" preserveAspectRatio="none" className="h-full w-full">
        {/* Fill the bulge between the panel's straight edge and the bent
            line with the nav tint, so the background follows the bend
            instead of exposing the page backdrop. Zero-area when at rest. */}
        <motion.path d={`${d} Z`} fill="var(--glass-tint-nav)" stroke="none" />
        <motion.path
          d={d}
          stroke="var(--glass-edge)"
          strokeWidth={hover ? 2.5 : 1.5}
          fill="none"
          strokeLinecap="round"
          style={{ transition: "stroke-width 120ms ease-out" }}
        />
      </svg>
      {/* Collapse affordance: a small arrow chip riding the line's midpoint,
          revealed while the rail is hovered. It follows the bend (the bowed
          quadratic's midpoint sits at half the control-point offset) and
          wears the same glass-card treatment as the app's other chips.
          Direction tracks what a click will do (collapse vs expand). */}
      <span
        aria-hidden
        className={cn(
          "pointer-events-none absolute top-1/2 left-1/2 flex size-5 items-center justify-center rounded-full border border-[var(--glass-edge)] bg-[var(--glass-tint-card)] text-foreground [box-shadow:var(--shadow-bubble-rest)] transition-opacity duration-150",
          hover ? "opacity-100" : "opacity-0",
        )}
        style={{
          transform: `translate(calc(-50% + ${bowVal / 2}px), -50%)`,
          backdropFilter: "blur(var(--glass-blur))",
          WebkitBackdropFilter: "blur(var(--glass-blur))",
        }}
      >
        {(side === "left") !== (state === "collapsed") ? (
          <ChevronLeft className="size-3" />
        ) : (
          <ChevronRight className="size-3" />
        )}
      </span>
    </button>
  );
}

/**
 * Sidebar rail body. The shadcn `<Sidebar>` primitive provides the collapse
 * mechanics; we layer a glass tint + bubbly border-radius on the inner wrapper
 * so the rail reads as a refractive surface against the dashboard backdrop.
 * Tier-3 CSS (mt-liquid-css) is applied directly — `LiquidSurface` is for
 * card-shaped raised surfaces, not full-height nav rails (different
 * border-radius and edge treatment).
 */
export function BendingSidebar({
  children,
  side = "left",
  className,
}: {
  children: React.ReactNode;
  side?: "left" | "right";
  className?: string;
}) {
  return (
    <Sidebar
      collapsible="icon"
      side={side}
      className={cn(
        "transition-[width] duration-150 ease-[cubic-bezier(0.32,0.72,0,1)]",
        // Suppress shadcn's own container border — the glass panel below owns
        // the single rim, otherwise the two borders double up (visible on
        // collapse).
        "!border-0",
        // The primitive's inner wrapper paints an opaque bg-sidebar layer,
        // which reads as a tone shift against the content pane at the rail.
        // Kill it so the page backdrop flows through the glass on both sides
        // of the edge line.
        "[&_[data-sidebar=sidebar]]:!bg-transparent",
        className,
      )}
    >
      <div
        className={cn(
          "mt-liquid-css flex h-full w-full flex-col text-sidebar-foreground",
          // No panel border — the BendingRail SVG below draws the single
          // inner-edge line. (The glass border + the rail were doubling up,
          // and the bubble rounding gapped the top/bottom corners.)
          "!border-0",
        )}
        data-variant="nav"
        // The sidebar surface must be pixel-identical to the content pane:
        // no tint, no inner-edge depth shadow, no backdrop blur. The edge
        // line is the only divider. (mt-liquid-css nav paints all three.)
        style={{
          background: "transparent",
          boxShadow: "none",
          backdropFilter: "none",
          WebkitBackdropFilter: "none",
        }}
      >
        {children}
      </div>
      <BendingRail side={side} />
    </Sidebar>
  );
}

export function BendingSidebarHeader({
  title,
  subtitle,
  icon: Icon,
  className,
}: {
  title: string;
  subtitle?: string;
  icon?: LucideIcon;
  className?: string;
}) {
  return (
    <SidebarHeader
      className={cn(
        // Pin to the shared chrome height so this border-b lines up with the
        // content header's (MT-05). Center the row in that fixed height.
        "h-[var(--chrome-header-h)] justify-center border-b border-[var(--glass-edge)]",
        className,
      )}
    >
      <div className="flex items-center gap-2 px-1">
        {Icon && (
          <div className="flex size-8 shrink-0 items-center justify-center rounded-bubble-sm bg-[var(--color-gold-soft)] text-[var(--color-gold)] [box-shadow:var(--shadow-bubble-rest)]">
            <Icon className="size-4" />
          </div>
        )}
        <div className="min-w-0 group-data-[collapsible=icon]:hidden">
          <div className="truncate text-sm font-semibold">{title}</div>
          {subtitle && <div className="truncate text-xs text-muted-foreground">{subtitle}</div>}
        </div>
      </div>
    </SidebarHeader>
  );
}

export function BendingSidebarNav({
  items,
  renderLink,
  className,
}: {
  items: NavItem[];
  /** Render a navigation link. Receives item + className + children. */
  renderLink?: (
    item: NavItem,
    props: {
      className: string;
      children: React.ReactNode;
    },
  ) => React.ReactNode;
  className?: string;
}) {
  const reduced = useReducedMotion();
  return (
    <SidebarContent className={className}>
      <SidebarMenu className="gap-1.5 px-2 py-5">
        {items.map((item) => {
          const Icon = item.icon;
          const buttonContent = (
            <>
              <Icon className="size-4 shrink-0" />
              <span className="truncate group-data-[collapsible=icon]:hidden">{item.label}</span>
              {item.badge && (
                <span
                  className={cn(
                    "ml-auto rounded-bubble-pill px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide",
                    "bg-[var(--color-gold-soft)] text-[var(--color-gold)]",
                    "group-data-[collapsible=icon]:hidden",
                  )}
                >
                  {item.badge}
                </span>
              )}
            </>
          );
          // Active highlight is a refractive pill that lights up the row.
          // Hover uses a subtle scale-spring; press feels squishy.
          // The base styling SidebarMenuButton used to contribute, now applied
          // to the link itself. The link owns its box: no `!p-0` (its
          // !important would zero out linkClass's pl-7/pr-4/py-3) and h-auto
          // so the variants' fixed h-8 doesn't pin the row at 32px.
          const menuButtonClass = cn(
            sidebarMenuButtonVariants({ variant: "default", size: "default" }),
            "h-auto hover:bg-transparent data-[active=true]:bg-transparent",
          );
          const linkClass = cn(
            "group/nav-item relative flex w-full items-center gap-3 overflow-hidden rounded-bubble-md px-4 py-2.5 text-left text-sm",
            "group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:px-0",
            "transition-[background-color,color,box-shadow] duration-200",
            item.active
              ? "border border-[var(--glass-edge)] bg-[var(--color-sidebar-accent)] text-[var(--color-sidebar-accent-foreground)]"
              : "text-sidebar-foreground hover:bg-[var(--glass-tint-card)] hover:text-foreground",
          );
          return (
            <SidebarMenuItem key={item.to} data-tour={item.dataTour}>
              {/* React Aria's SidebarMenuButton has no `asChild`, and it
                  renders a <button> unless given an href — nesting the router
                  link inside one would be invalid HTML. So the link itself
                  carries the button styling via sidebarMenuButtonVariants,
                  which is exactly what the Slot was doing before. */}
              {renderLink ? (
                renderLink(item, {
                  className: cn(menuButtonClass, linkClass),
                  children: buttonContent,
                })
              ) : (
                <a
                  href={item.to}
                  onClick={item.onClick}
                  data-active={item.active || undefined}
                  className={cn(menuButtonClass, linkClass)}
                >
                  {buttonContent}
                </a>
              )}
              {/* Squishy press feedback. Mounted as overlay to keep the link's
                  semantics intact. */}
              {!reduced && (
                <motion.span
                  aria-hidden
                  whileTap={{ scale: 0.96 }}
                  className="pointer-events-none absolute inset-0 -z-10"
                />
              )}
            </SidebarMenuItem>
          );
        })}
      </SidebarMenu>
    </SidebarContent>
  );
}

export function BendingSidebarFooter({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <SidebarFooter className={cn("border-t border-[var(--glass-edge)]", className)}>
      {children}
    </SidebarFooter>
  );
}
